typedef struct {const void*p;size_t n;} Span;
typedef struct {CohBytes b;size_t at,end,work;CohStatus status;const CohBaseDetailInventoryControl*control;} Read;
#define ALIGNED(p,t) ((uintptr_t)(p)%offsetof(struct{char c;t v;},v)==0)
static int valid(Span s){return s.p?(uintptr_t)s.p<=UINTPTR_MAX-s.n:!s.n;}
static int overlap(Span a,Span b){return a.n&&b.n&&(uintptr_t)a.p<(uintptr_t)b.p+b.n&&(uintptr_t)b.p<(uintptr_t)a.p+a.n;}
static int nonzero(const uint8_t*p){unsigned n=0;for(unsigned i=0;i<32;i++)n|=p[i];return n!=0;}
static void need(Read*r,int ok,CohStatus s){if(r->status==COH_OK&&!ok)r->status=s;}
static int charge(Read*r,size_t n){if(r->status!=COH_OK)return 0;if(n>COH_BASEDETAIL_WORK_MAX-r->work){r->status=COH_LIMIT;return 0;}r->work+=n;return 1;}
static void poll(Read*r){if(charge(r,1)&&r->control->cancel.poll&&r->control->cancel.poll(r->control->cancel.context))r->status=COH_CANCELLED;}
static const uint8_t*take(Read*r,size_t n){if(!charge(r,n))return NULL;if(r->at>r->end||n>r->end-r->at){r->status=COH_INVALID;return NULL;}const uint8_t*p=r->b.data+r->at;r->at+=n;return p;}
static uint32_t word(Read*r){const uint8_t*p=take(r,4);return p?(uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24:0;}
static size_t segment(Read*r){uint32_t n=word(r);need(r,r->at<=r->end&&n<=r->end-r->at,COH_INVALID);return r->status==COH_OK?r->at+n:r->at;}
static CohBytes text(Read*r){CohBytes b={0};const uint8_t*p=take(r,2);if(!p)return b;size_t n=(size_t)p[0]|(size_t)p[1]<<8;need(r,n<COH_SALVAGE_STRING_MAX,COH_LIMIT);p=take(r,n);if(!p)return b;for(size_t i=0;i<n&&r->status==COH_OK;i++){if(!charge(r,1))break;need(r,p[i]!=0,COH_INVALID);}b=(CohBytes){p,n};(void)take(r,(4-(n+2)%4)%4);return b;}
static CohSalvageText copy(Read*r,CohBaseDetailInventory*d,CohBytes b){CohSalvageText t={0,0};need(r,b.size>0&&b.size<128,COH_UNSUPPORTED);for(size_t i=0;i<b.size&&r->status==COH_OK;i++){if(!charge(r,1))break;need(r,b.data[i]>0&&b.data[i]<128,COH_UNSUPPORTED);}need(r,b.size+1<=COH_BASEDETAIL_TEXT_MAX-d->text_bytes,COH_LIMIT);if(r->status!=COH_OK||!charge(r,b.size+1))return t;t=(CohSalvageText){d->text_bytes,(uint32_t)b.size};memcpy(d->text+t.offset,b.data,b.size);d->text_bytes+=(uint32_t)b.size+1;return t;}
static int literal(Read*r,CohBytes b,const char*s){size_t n=strlen(s);return charge(r,b.size)&&b.size==n&&!memcmp(b.data,s,n);}
static void parse(Read*r,CohBaseDetailInventory*d){r->at=0;r->end=r->b.size;const uint8_t*p=take(r,8);need(r,p&&!memcmp(p,"CrypticS",8),COH_INVALID);d->schema_crc=word(r);need(r,d->schema_crc==UINT32_C(0x6f0830ea),COH_STATE);CohBytes sig=text(r),files=text(r);need(r,literal(r,sig,"Parse6")&&literal(r,files,"Files1"),COH_UNSUPPORTED);size_t end=segment(r),outer=r->end;r->end=end;d->dependencies=word(r);need(r,d->dependencies<=4096,COH_LIMIT);for(unsigned i=0;i<d->dependencies&&r->status==COH_OK;i++){poll(r);(void)text(r);(void)word(r);}need(r,r->at==end,COH_INVALID);r->end=outer;end=segment(r);need(r,end==r->end,COH_INVALID);d->id_count=word(r);need(r,d->id_count<=COH_BASEDETAIL_ROWS_MAX,COH_LIMIT);for(unsigned i=0;i<d->id_count&&r->status==COH_OK;i++){size_t row=segment(r);outer=r->end;r->end=row;poll(r);uint32_t u=word(r);memcpy(&d->id_rows[i].id,&u,4);d->id_rows[i].name=copy(r,d,text(r));need(r,r->at==row,COH_INVALID);r->end=outer;}need(r,r->at==r->end,COH_INVALID);}
static unsigned fold(unsigned c){return c>='A'&&c<='Z'?c+32:c;}
static int same(Read*r,const CohBaseDetailInventory*d,CohSalvageText a,CohSalvageText b){if(!charge(r,1)||a.size!=b.size)return 0;for(unsigned i=0;i<a.size;i++){if(!charge(r,1))return 0;if(fold((unsigned char)d->text[a.offset+i])!=fold((unsigned char)d->text[b.offset+i]))return 0;}return 1;}
static void finalize(Read*r,CohBaseDetailInventory*d){for(unsigned i=0;i<d->id_count&&r->status==COH_OK;i++){poll(r);if(d->id_rows[i].id>0){uint32_t id=(uint32_t)d->id_rows[i].id;need(r,id<COH_BASEDETAIL_IDS_MAX,COH_LIMIT);if(id>d->max_id)d->max_id=id;}}need(r,d->max_id>0,COH_STATE);uint32_t next=d->max_id+1;for(unsigned i=0;i<d->count&&r->status==COH_OK;i++){poll(r);CohBaseDetailIdentity*entry=&d->entries[i];int duplicate=0;for(unsigned j=0;j<i&&r->status==COH_OK;j++)if(same(r,d,entry->name,d->entries[j].name)){duplicate=1;break;}if(duplicate)continue;uint32_t id=0;for(unsigned j=0;j<d->id_count&&r->status==COH_OK;j++){if(!charge(r,1))break;if(d->id_rows[j].id>0&&same(r,d,entry->name,d->id_rows[j].name)){id=(uint32_t)d->id_rows[j].id;break;}}if(!id){need(r,next<COH_BASEDETAIL_IDS_MAX,COH_LIMIT);id=next++;}if(r->status!=COH_OK)break;entry->id=id;entry->active=1;d->active_count++;d->slots[id]=i+1;if(id>=d->slot_count)d->slot_count=id+1;}}
static int source_owner(const CohSalvageDictionary*d){return d->complete==1&&d->provenance&&!d->runtime_generation&&!d->actor_authority&&d->schema_crc[0]==UINT32_C(0x5b9c4ac0)&&d->schema_crc[1]==UINT32_C(0x6f0830ea)&&d->schema_crc[2]==UINT32_C(0x326ad4e9)&&d->count<=COH_SALVAGE_MAX&&d->id_count<=COH_SALVAGE_MAX&&d->details_count<=COH_BASEDETAIL_ROWS_MAX&&d->text_bytes<=COH_SALVAGE_TEXT_MAX&&d->value_count<=COH_SALVAGE_VALUES_MAX&&d->slot_count<=COH_SALVAGE_IDS_MAX&&d->tab_count<=COH_SALVAGE_MAX&&nonzero(d->sha256[0])&&nonzero(d->sha256[1])&&nonzero(d->sha256[2]);}
CohStatus coh_basedetail_inventory_read(const CohBaseDetailInventorySources*s,const CohSalvageDictionary*details,const CohCostumeImportDigest*d,const CohBaseDetailInventoryControl*c,CohBaseDetailInventory*out,CohBaseDetailInventoryWorkspace*w,size_t budget,size_t retained){
 if(!s||!details||!d||!c||!out||!w||!ALIGNED(s,CohBaseDetailInventorySources)||!ALIGNED(details,CohSalvageDictionary)||!ALIGNED(d,CohCostumeImportDigest)||!ALIGNED(c,CohBaseDetailInventoryControl)||!ALIGNED(out,CohBaseDetailInventory)||!ALIGNED(w,CohBaseDetailInventoryWorkspace)||!budget||budget>COH_BASEDETAIL_RAM_MAX)return COH_INVALID;
 Span fixed[]={{s,sizeof(*s)},{details,sizeof(*details)},{d,sizeof(*d)},{c,sizeof(*c)},{out,sizeof(*out)},{w,sizeof(*w)}};size_t used=COH_BASEDETAIL_STACK_RESERVE;
 for(unsigned i=0;i<6;i++){if(!valid(fixed[i]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(fixed[i],fixed[j]))return COH_INVALID;if(fixed[i].n>budget||used>budget-fixed[i].n)return COH_LIMIT;used+=fixed[i].n;}
 if(!s->ids.data||!s->ids.size||s->ids.size>COH_BASEDETAIL_INPUT_MAX)return COH_LIMIT;
 if(!d->sha256||(!d->context!=!d->context_bytes)||(!c->cancel.context!=!c->context_bytes))return COH_INVALID;
 Span variable[]={{s->ids.data,s->ids.size},{d->context,d->context_bytes},{c->cancel.context,c->context_bytes}};
 for(unsigned i=0;i<3;i++){if(!valid(variable[i]))return COH_INVALID;for(unsigned j=0;j<6;j++)if(overlap(variable[i],fixed[j]))return COH_INVALID;for(unsigned j=0;j<i;j++)if(overlap(variable[i],variable[j]))return COH_INVALID;if(variable[i].n>budget-used)return COH_LIMIT;used+=variable[i].n;}
 if(d->scratch_reserve>budget-used)return COH_LIMIT;
 used+=d->scratch_reserve;if(c->scratch_reserve>budget-used)return COH_LIMIT;
 used+=c->scratch_reserve;if(retained>budget-used)return COH_LIMIT;
 if(!source_owner(details)||s->provenance!=details->provenance||!nonzero(s->expected_ids_sha256)||!nonzero(s->expected_details_sha256)||memcmp(s->expected_details_sha256,details->sha256[2],32))return COH_STATE;
 Read r={s->ids,0,0,0,COH_OK,c};poll(&r);if(r.status!=COH_OK)return r.status;CohBaseDetailInventory*v=&w->candidate;memset(v,0,sizeof(*v));v->provenance=s->provenance;memcpy(v->source_sha256,details->sha256,96);v->count=details->details_count;
 for(unsigned i=0;i<v->count&&r.status==COH_OK;i++){poll(&r);CohSalvageText t=details->details[i];need(&r,t.offset<details->text_bytes&&t.size<details->text_bytes-t.offset,COH_STATE);if(r.status==COH_OK){need(&r,details->text[t.offset+t.size]==0,COH_STATE);if(r.status==COH_OK)v->entries[i].name=copy(&r,v,(CohBytes){(const uint8_t*)details->text+t.offset,t.size});}}
 if(r.status!=COH_OK)return r.status;
 parse(&r,v);if(r.status!=COH_OK)return r.status;finalize(&r,v);if(r.status!=COH_OK)return r.status;poll(&r);if(r.status!=COH_OK)return r.status;CohStatus status=d->sha256(d->context,s->ids,v->ids_sha256);if(status!=COH_OK)return status;if(memcmp(v->ids_sha256,s->expected_ids_sha256,32))return COH_STATE;poll(&r);if(r.status!=COH_OK)return r.status;v->complete=1;*out=*v;return COH_OK;
}
static CohStatus owner(const CohBaseDetailInventory*d,uint32_t*out){Span a={d,sizeof(*d)},b={out,sizeof(*out)};if(!d||!out||!ALIGNED(d,CohBaseDetailInventory)||!ALIGNED(out,uint32_t)||!valid(a)||!valid(b)||overlap(a,b))return COH_INVALID;if(d->complete!=1||!d->provenance||d->runtime_generation||d->actor_authority||d->schema_crc!=UINT32_C(0x6f0830ea)||d->count>COH_BASEDETAIL_ROWS_MAX||d->id_count>COH_BASEDETAIL_ROWS_MAX||d->slot_count>COH_BASEDETAIL_IDS_MAX||d->text_bytes>COH_BASEDETAIL_TEXT_MAX||d->active_count>d->count)return COH_STATE;return COH_OK;}
static CohStatus query(const CohBaseDetailInventory*d,CohBytes name,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;Span a={name.data,name.size},b={out,sizeof(*out)};if(!name.data||!valid(a)||overlap(a,b))return COH_INVALID;if(!name.size||name.size>=128)return COH_UNSUPPORTED;for(size_t i=0;i<name.size;i++)if(!name.data[i]||name.data[i]>=128)return COH_UNSUPPORTED;return COH_OK;}
static int match(const CohBaseDetailInventory*d,CohSalvageText t,CohBytes name){if(t.offset>=d->text_bytes||t.size>=d->text_bytes-t.offset||d->text[t.offset+t.size])return -1;if(t.size!=name.size)return 0;for(unsigned i=0;i<t.size;i++){unsigned c=(unsigned char)d->text[t.offset+i];if(!c||c>=128)return -1;if(fold(c)!=fold(name.data[i]))return 0;}return 1;}
CohStatus coh_basedetail_inventory_find(const CohBaseDetailInventory*d,CohBytes name,uint32_t*out){CohStatus s=query(d,name,out);if(s!=COH_OK)return s;for(unsigned i=0;i<d->count;i++){if(!d->entries[i].active)continue;int m=match(d,d->entries[i].name,name);if(m<0)return COH_STATE;if(m){*out=i;return COH_OK;}}return COH_NOT_FOUND;}
CohStatus coh_basedetail_inventory_by_id(const CohBaseDetailInventory*d,uint32_t id,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;if(!id||id>=d->slot_count||!d->slots[id])return COH_NOT_FOUND;unsigned row=d->slots[id]-1;if(row>=d->count||d->entries[row].active!=1||d->entries[row].id!=id)return COH_STATE;*out=row;return COH_OK;}
CohStatus coh_basedetail_inventory_join(const CohBaseDetailInventory*d,CohBytes name,uint32_t id,uint32_t*out){CohStatus s=query(d,name,out);if(s!=COH_OK)return s;uint32_t a,b;s=coh_basedetail_inventory_find(d,name,&a);if(s!=COH_OK)return s;s=coh_basedetail_inventory_by_id(d,id,&b);if(s!=COH_OK)return s;if(a!=b)return COH_NOT_FOUND;*out=a;return COH_OK;}
CohStatus coh_basedetail_inventory_id_find(const CohBaseDetailInventory*d,CohBytes name,uint32_t*out){CohStatus s=query(d,name,out);if(s!=COH_OK)return s;for(unsigned i=0;i<d->id_count;i++){if(d->id_rows[i].id<=0)continue;int m=match(d,d->id_rows[i].name,name);if(m<0)return COH_STATE;if(m){*out=i;return COH_OK;}}return COH_NOT_FOUND;}
CohStatus coh_basedetail_inventory_id_name(const CohBaseDetailInventory*d,uint32_t id,uint32_t*out){CohStatus s=owner(d,out);if(s!=COH_OK)return s;if(!id||id>=COH_BASEDETAIL_IDS_MAX)return COH_NOT_FOUND;for(unsigned i=0;i<d->id_count;i++)if(d->id_rows[i].id==(int32_t)id){*out=i;return COH_OK;}return COH_NOT_FOUND;}
